messages.content:
Tool response:
Tool: create_aliquot_event
Description: Create Aliquot Event
Parameters:
    {
      "type": "object",
      "properties": {
        "specimen_id": {
          "type": "string",
          "title": "Specimen Id",
          "description": "The external identifier of the specimen to be aliquoted"
        },
        "protocol_name": {
          "type": "string",
          "title": "Protocol Name",
          "description": "The name of the protocol used for aliquoting"
        },
        "operator_initials": {
          "type": "string",
          "title": "Operator Initials",
          "description": "The initials of the operator performing the aliquoting"
        },
        "qc_note": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Qc Note",
          "description": "Quality control notes related to the aliquoting process"
        },
        "aliquots": {
          "items": {
            "properties": {
              "container_id": {
                "type": "string",
                "title": "Container Id",
                "description": "The external identifier of the container"
              },
              "position": {
                "type": "string",
                "title": "Position",
                "description": "Position within the container (e.g., A01)"
              },
              "volume_ml": {
                "type": "number",
                "title": "Volume Ml",
                "description": "Volume in milliliters"
              }
            },
            "type": "object",
            "required": [
              "container_id",
              "position",
              "volume_ml"
            ],
            "title": "AliquotItem"
          },
          "type": "array",
          "title": "Aliquots",
          "description": "List of aliquot details including container ID, position, and volume"
        }
      },
      "required": [
        "specimen_id",
        "protocol_name",
        "operator_initials",
        "aliquots"
      ]
    }
